public class Restaurant
{
    public Guid Id { get; } = Guid.NewGuid();
    public string Name { get; set; }
    public Address Address { get; set; }
    public List<MenuItem> Menu { get; } = new();
    public decimal AverageRating { get; set; }
}

public class Order
{
    public Guid Id { get; } = Guid.NewGuid();
    public Guid CustomerId { get; set; }
    public Guid RestaurantId { get; set; }
    public List<OrderItem> Items { get; } = new();
    public OrderStatus Status { get; set; }
    public Guid? DeliveryPartnerId { get; set; }
    public DateTime CreatedAt { get; } = DateTime.UtcNow;
}

public class Delivery
{
    public Guid OrderId { get; set; }
    public Guid PartnerId { get; set; }
    public GeoLocation CurrentLocation { get; set; }
    public DateTime EstimatedArrival { get; set; }
    public DeliveryStatus Status { get; set; }
}

public enum OrderStatus { Placed, Accepted, Preparing, PickedUp, Delivered, Cancelled }
public enum DeliveryStatus { Searching, Assigned, PickedUp, Delivered }
